const {
  buildActivity,
  createRequestOptions,
  fallbackActivity,
  parseDotenv,
  resolveToken,
} = require('../../scripts/fetch-github-activity');

describe('fetch-github-activity script helpers', () => {
  it('reads portfolio token first without printing or mutating values', () => {
    const fileEnv = parseDotenv(`
      GITHUB_TOKEN=file-token
      GITHUB_TOKEN_PORTFOLIO="portfolio-file-token"
    `);

    expect(fileEnv).toEqual({
      GITHUB_TOKEN: 'file-token',
      GITHUB_TOKEN_PORTFOLIO: 'portfolio-file-token',
    });
    expect(
      resolveToken(
        {
          GITHUB_TOKEN: 'process-token',
          GITHUB_TOKEN_PORTFOLIO: 'portfolio-process-token',
        },
        fileEnv
      )
    ).toBe('portfolio-process-token');
  });

  it('adds Authorization only inside request options when a token exists', () => {
    expect(createRequestOptions('/users/aatif101', '').headers.Authorization).toBeUndefined();
    expect(createRequestOptions('/users/aatif101', 'secret-token').headers.Authorization).toBe(
      'Bearer secret-token'
    );
  });

  it('builds a sanitized public activity artifact from GitHub payloads', () => {
    const activity = buildActivity({
      profile: {
        login: 'aatif101',
        name: 'Mohammad Aatif Shaikh',
        html_url: 'https://github.com/aatif101',
        bio: 'Builder',
        public_repos: 2,
        followers: 7,
      },
      repos: [
        {
          private: false,
          name: 'fresh',
          full_name: 'aatif101/fresh',
          html_url: 'https://github.com/aatif101/fresh',
          description: 'Recent work',
          homepage: '',
          language: 'JavaScript',
          stargazers_count: 3,
          forks_count: 1,
          fork: false,
          archived: false,
          topics: ['portfolio'],
          pushed_at: '2026-01-01T00:00:00Z',
          updated_at: '2026-01-02T00:00:00Z',
        },
        {
          private: true,
          name: 'private-work',
        },
      ],
      events: [
        {
          id: '1',
          type: 'PushEvent',
          repo: { name: 'aatif101/fresh' },
          created_at: '2026-01-03T00:00:00Z',
          payload: { commits: [{ sha: 'abc', message: 'Ship safely' }] },
        },
      ],
    });

    expect(activity.fallback).toBe(false);
    expect(activity.source).toBe('github-rest');
    expect(activity.repositories).toHaveLength(1);
    expect(activity.repositories[0]).not.toHaveProperty('private');
    expect(activity.signals.totalStars).toBe(3);
    expect(activity.signals.topLanguages).toEqual([{ language: 'JavaScript', count: 1 }]);
    expect(activity.recentActivity[0]).toMatchObject({ type: 'PushEvent', repo: 'aatif101/fresh' });
  });

  it('provides a graceful fallback shape for missing token or API failure', () => {
    const fallback = fallbackActivity('missing token');

    expect(fallback).toMatchObject({
      username: 'aatif101',
      source: 'fallback',
      fallback: true,
      fallbackReason: 'missing token',
    });
    expect(fallback.profile.htmlUrl).toBe('https://github.com/aatif101');
    expect(fallback.repositories).toEqual([]);
    expect(fallback.recentActivity).toEqual([]);
  });
});

import React from 'react';

const labelStyle = {
  fontFamily: 'var(--font-sans)',
  fontSize: 'var(--text-xs)',
  letterSpacing: 'var(--tracking-caps)',
  textTransform: 'uppercase',
  color: 'var(--color-muted)',
  marginBottom: 'var(--space-4)',
};

const headingStyle = {
  fontFamily: 'var(--font-serif)',
  fontSize: 'var(--text-3xl)',
  fontWeight: 300,
  lineHeight: 'var(--leading-tight)',
  letterSpacing: 'var(--tracking-tight)',
  color: 'var(--color-ink)',
  margin: '0 0 var(--space-16)',
};

/**
 * Reusable editorial section shell.
 * Props:
 *   id           — anchor id for the <section>
 *   label        — small-caps eyebrow label (e.g. "Experience")
 *   heading      — display heading (e.g. "Work")
 *   surface      — "paper" | "surface" (defaults to "paper")
 *   motionReveal — when true, stamps data-motion-reveal for scroll choreography
 *   children     — content slot filled by later slices
 */
export default function SectionShell({ id, label, heading, surface = 'paper', motionReveal = false, children }) {
  const headingId = `${id}-heading`;
  const bg = surface === 'surface' ? 'var(--color-surface)' : 'var(--color-paper)';

  return (
    <section
      id={id}
      aria-labelledby={headingId}
      {...(motionReveal ? { 'data-motion-reveal': '' } : {})}
      style={{
        backgroundColor: bg,
        padding: 'var(--space-24) var(--space-8)',
        borderBottom: '1px solid var(--color-hairline)',
      }}
    >
      <div style={{ maxWidth: 'var(--col-prose)', margin: '0 auto' }}>
        <p style={labelStyle}>{label}</p>
        <h2 id={headingId} style={headingStyle}>
          {heading}
        </h2>
        {children}
      </div>
    </section>
  );
}

import React from 'react';

const spreadStyle = {
  display: 'grid',
  gridTemplateColumns: 'minmax(8rem, 0.45fr) minmax(0, 1fr)',
  gap: 'var(--space-8)',
  padding: 'var(--space-12) 0',
  borderTop: '1px solid var(--color-hairline)',
};

const metaStyle = {
  fontFamily: 'var(--font-sans)',
  fontSize: 'var(--text-xs)',
  letterSpacing: 'var(--tracking-caps)',
  textTransform: 'uppercase',
  color: 'var(--color-muted)',
  lineHeight: 'var(--leading-loose)',
};

const titleStyle = {
  fontFamily: 'var(--font-serif)',
  fontSize: 'var(--text-2xl)',
  fontWeight: 300,
  lineHeight: 'var(--leading-tight)',
  letterSpacing: 'var(--tracking-tight)',
  color: 'var(--color-ink)',
  margin: '0 0 var(--space-4)',
};

const bodyStyle = {
  fontFamily: 'var(--font-serif)',
  fontSize: 'var(--text-md)',
  lineHeight: 'var(--leading-prose)',
  color: 'var(--color-ink)',
  margin: '0 0 var(--space-6)',
};

export default function SelectedWork({ works }) {
  return (
    <div aria-label="Pinned selected work">
      {works.map((work, index) => (
        <article key={work.id} style={spreadStyle}>
          <aside style={metaStyle} aria-label={`${work.name} metadata`}>
            <div>{String(index + 1).padStart(2, '0')}</div>
            <div>{work.role}</div>
            <div>{work.status}</div>
          </aside>

          <div>
            <p style={{ ...metaStyle, color: 'var(--color-oxblood)', margin: '0 0 var(--space-3)' }}>
              {work.name}
            </p>
            <h3 style={titleStyle}>
              {work.href ? (
                <a
                  href={work.href}
                  style={{ color: 'inherit', textDecorationColor: 'var(--color-oxblood)' }}
                >
                  {work.title}
                </a>
              ) : (
                work.title
              )}
            </h3>
            <p style={bodyStyle}>{work.summary}</p>
            <ul
              style={{
                listStyle: 'none',
                padding: 0,
                margin: 0,
                display: 'grid',
                gap: 'var(--space-3)',
              }}
            >
              {work.details.map((detail) => (
                <li
                  key={detail}
                  style={{
                    fontFamily: 'var(--font-sans)',
                    fontSize: 'var(--text-sm)',
                    lineHeight: 'var(--leading-relaxed)',
                    color: 'var(--color-muted)',
                  }}
                >
                  {detail}
                </li>
              ))}
            </ul>
          </div>
        </article>
      ))}
    </div>
  );
}

import React from 'react';
import portfolioContent from '../../content/portfolioContent';

/**
 * Opening spread — the lede section of the one-page portfolio.
 * Book-like: no cards, no icons, no gradients, no shadows.
 */
export default function OpeningSpread() {
  const { lede, identity } = portfolioContent;

  return (
    <section
      id="about"
      aria-labelledby="about-heading"
      style={{
        backgroundColor: 'var(--color-paper)',
        padding: 'var(--space-32) var(--space-8) var(--space-24)',
        borderBottom: '1px solid var(--color-hairline)',
      }}
    >
      <div data-motion-hero style={{ maxWidth: 'var(--col-prose)', margin: '0 auto' }}>
        <p
          style={{
            fontFamily: 'var(--font-sans)',
            fontSize: 'var(--text-xs)',
            letterSpacing: 'var(--tracking-caps)',
            textTransform: 'uppercase',
            color: 'var(--color-muted)',
            marginBottom: 'var(--space-8)',
          }}
        >
          {lede.eyebrow} &mdash; {identity.location}
        </p>

        <h2
          id="about-heading"
          style={{
            fontFamily: 'var(--font-serif)',
            fontSize: 'var(--text-4xl)',
            fontWeight: 300,
            lineHeight: 'var(--leading-tight)',
            letterSpacing: 'var(--tracking-tight)',
            color: 'var(--color-ink)',
            margin: '0 0 var(--space-8)',
          }}
        >
          {lede.title}
        </h2>

        {lede.body.map((paragraph) => (
          <p
            key={paragraph}
            style={{
              fontFamily: 'var(--font-serif)',
              fontSize: 'var(--text-lg)',
              lineHeight: 'var(--leading-prose)',
              color: 'var(--color-ink)',
              maxWidth: '52ch',
              margin: '0 0 var(--space-5)',
            }}
          >
            {paragraph}
          </p>
        ))}
      </div>
    </section>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ─── Editorial Design Tokens ──────────────────────────────────────────────── */

:root {
  /* Color — warm paper editorial palette */
  --color-paper:      #f5f1eb;
  --color-ink:        #1a1714;
  --color-muted:      #6b6560;
  --color-faint:      #c8c2ba;
  --color-oxblood:    #7a1d1d;
  --color-accent:     #9b3b1e;
  --color-hairline:   #ddd8d0;
  --color-surface:    #ede9e2;

  /* Typography */
  --font-serif:       'Spectral', 'Plantin', 'Georgia', serif;
  --font-sans:        'Inter', system-ui, -apple-system, sans-serif;

  /* Type scale (fluid) */
  --text-xs:          0.75rem;
  --text-sm:          0.875rem;
  --text-base:        1.0625rem;
  --text-lg:          1.25rem;
  --text-xl:          1.5rem;
  --text-2xl:         2rem;
  --text-3xl:         2.75rem;
  --text-4xl:         3.75rem;
  --text-5xl:         5rem;

  /* Leading */
  --leading-tight:    1.15;
  --leading-snug:     1.35;
  --leading-prose:    1.7;

  /* Tracking */
  --tracking-tight:   -0.02em;
  --tracking-wide:    0.08em;
  --tracking-caps:    0.12em;

  /* Spacing rhythm */
  --space-1:          0.25rem;
  --space-2:          0.5rem;
  --space-3:          0.75rem;
  --space-4:          1rem;
  --space-6:          1.5rem;
  --space-8:          2rem;
  --space-12:         3rem;
  --space-16:         4rem;
  --space-24:         6rem;
  --space-32:         8rem;
  --space-48:         12rem;

  /* Max-width column */
  --col-prose:        68ch;
  --col-wide:         90rem;

  /* Transitions */
  --ease-out:         cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast:    120ms;
  --duration-base:    240ms;
  --duration-slow:    400ms;
}

/* ─── Base Layer ────────────────────────────────────────────────────────────── */

@layer base {
  *,
  *::before,
  *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    scroll-behavior: smooth;
    -webkit-text-size-adjust: 100%;
    text-size-adjust: 100%;
  }

  body {
    font-family: var(--font-serif);
    font-size: var(--text-base);
    line-height: var(--leading-prose);
    background-color: var(--color-paper);
    color: var(--color-ink);
    overflow-x: hidden;
    /* Font rendering */
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    font-feature-settings: 'kern' 1, 'liga' 1, 'onum' 1;
    /* Balanced text wrapping (Chrome 114+, Firefox 121+) */
    text-wrap: pretty;
  }

  /* Headings default to serif */
  h1, h2, h3, h4, h5, h6 {
    font-family: var(--font-serif);
    font-weight: 500;
    letter-spacing: var(--tracking-tight);
    line-height: var(--leading-tight);
    text-wrap: balance;
    color: var(--color-ink);
  }

  /* Focused elements — visible, consistent, branded */
  :focus-visible {
    outline: 2px solid var(--color-oxblood);
    outline-offset: 3px;
    border-radius: 2px;
  }

  /* Remove outline for mouse users */
  :focus:not(:focus-visible) {
    outline: none;
  }

  /* Links */
  a {
    color: inherit;
    text-decoration: none;
  }

  /* Images */
  img,
  picture,
  video,
  canvas,
  svg {
    display: block;
    max-width: 100%;
  }

  /* Form elements inherit typography */
  input,
  button,
  textarea,
  select {
    font: inherit;
  }

  /* Horizontal rule — hairline */
  hr {
    border: none;
    border-top: 1px solid var(--color-hairline);
  }
}

/* ─── Skip Link ─────────────────────────────────────────────────────────────── */

.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-4);
  z-index: 9999;
  padding: var(--space-2) var(--space-4);
  background: var(--color-ink);
  color: var(--color-paper);
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: var(--tracking-caps);
  text-transform: uppercase;
  text-decoration: none;
  border-radius: 0 0 4px 4px;
  transition: top var(--duration-fast) var(--ease-out);
}

.skip-link:focus {
  top: 0;
  outline: 2px solid var(--color-oxblood);
  outline-offset: 2px;
}

/* ─── Scroll Choreography ───────────────────────────────────────────────────── */

/* Progressive-enhancement: only hide elements once JS has confirmed motion is
   live (data-motion-ready stamped by useEditorialMotion). Before JS runs the
   elements are always visible — no flash-of-hidden-content. */

html[data-motion-ready='true'] [data-motion-hero],
html[data-motion-ready='true'] [data-motion-reveal] {
  /* GSAP sets opacity/transform inline; these just prevent a brief visible
     state between render and the first GSAP fromTo frame. */
  will-change: opacity, transform;
}

/* Reduced-motion variant: override any lingering will-change */
html[data-reduced-motion='true'] [data-motion-hero],
html[data-reduced-motion='true'] [data-motion-reveal] {
  will-change: auto;
}

/* ─── Reduced Motion ────────────────────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* ─── Utility Classes ───────────────────────────────────────────────────────── */

@layer utilities {
  .font-serif   { font-family: var(--font-serif); }
  .font-sans    { font-family: var(--font-sans); }

  .text-paper   { color: var(--color-paper); }
  .text-ink     { color: var(--color-ink); }
  .text-muted   { color: var(--color-muted); }
  .text-oxblood { color: var(--color-oxblood); }
  .text-accent  { color: var(--color-accent); }

  .bg-paper     { background-color: var(--color-paper); }
  .bg-surface   { background-color: var(--color-surface); }
  .bg-ink       { background-color: var(--color-ink); }

  .border-hairline { border-color: var(--color-hairline); }

  .tracking-caps   { letter-spacing: var(--tracking-caps); }
  .tracking-tight  { letter-spacing: var(--tracking-tight); }
  .tracking-wide   { letter-spacing: var(--tracking-wide); }

  .leading-prose  { line-height: var(--leading-prose); }
  .leading-tight  { line-height: var(--leading-tight); }
  .leading-snug   { line-height: var(--leading-snug); }

  .col-prose  { max-width: var(--col-prose); }
  .col-wide   { max-width: var(--col-wide); }
}

import React from 'react';
import { render, screen, within } from '@testing-library/react';
import '@testing-library/jest-dom';
import EditorialPortfolio from '../components/EditorialPortfolio';

/**
 * Smoke tests for the editorial shell.
 * These run after every build to catch legacy imports or missing sections.
 */

describe('EditorialPortfolio — section anchors and trusted content', () => {
  beforeEach(() => {
    render(<EditorialPortfolio />);
  });

